definition.script:
pipeline {
  agent { label 'build-agent-07' }
  options { buildDiscarder(logRotator(numToKeepStr: '30')) }
  stages {
    stage('Checkout') {
      steps {
        sh 'rm -rf src && git clone --quiet "$REPO_URL" src'
        sh 'cd src && git log -1 --format="Commit %h by %an: %s"'
        script {
          currentBuild.description = sh(returnStdout: true, script: 'cd src && git log -1 --format="%h %s"').trim()
        }
      }
    }
    stage('Test') {
      steps {
        sh 'cd src && python3 -m pytest -q -p no:cacheprovider'
      }
    }
    stage('Package') {
      steps {
        sh """
          dest=/srv/artifacts/route-eta-service/\$BUILD_NUMBER
          mkdir -p "\$dest"
          tar -czf "\$dest/route-eta-service.tgz" -C src .
          head -c 25000000 /dev/zero > "\$dest/debug-symbols.bin"
          echo "Archived build \$BUILD_NUMBER to \$dest"
        """
      }
    }
  }
}
